> **Insight:** Here's a plain-language summary for a developer: MSAL Node confidential client app setup. See the full details and steps below.


## Code Example

```javascript
// Required packages: @azure/msal-node (npm install @azure/msal-node)
// Security: store clientSecret in environment variables — never in source code.
const msal = require('@azure/msal-node');

const config = {
  auth: {
    clientId: process.env.CLIENT_ID,       // App registration client ID
    authority: 'https://login.microsoftonline.com/' + process.env.TENANT_ID,
    clientSecret: process.env.CLIENT_SECRET,  // ⚠ Keep this secret
  },
};

const cca = new msal.ConfidentialClientApplication(config);

// Exchange auth code for access token
async function getToken(authCode) {
  const tokenRequest = {
    code: authCode,
    scopes: ['User.Read'],
    redirectUri: process.env.REDIRECT_URI,
  };
  const response = await cca.acquireTokenByCode(tokenRequest);
  return response.accessToken;
}
```

